<?php $layoutTitle='Overview'; require __DIR__.'/views/layout-top.php'; $pdo=db(); $stats=[]; foreach(['farmers'=>'farmer','farms'=>'farm','crops'=>'crop','plantings'=>'planting','harvests'=>'harvest'] as $label=>$table) $stats[$label]=(int)$pdo->query("SELECT COUNT(*) FROM $table")->fetchColumn(); $sum=(float)$pdo->query('SELECT COALESCE(SUM(quantity_kg),0) FROM harvest')->fetchColumn(); $recent=$pdo->query("SELECT h.harvest_date,h.quantity_kg,c.crop_name,f.farm_name FROM harvest h JOIN planting p ON p.planting_id=h.planting_id JOIN crop c ON c.crop_id=p.crop_id JOIN farm f ON f.farm_id=p.farm_id ORDER BY h.harvest_date DESC,h.harvest_id DESC LIMIT 6")->fetchAll(); ?><section class="hero is-small welcome"><div class="hero-body"><div class="container"><p class="eyebrow">FIELD NOTES ? <?=date('F j, Y')?></p><h1 class="title is-2">A clearer view of your fields.</h1><p class="subtitle is-6">Track growers, farms, crop cycles, and harvests in one place.</p></div></div></section><section class="section pt-5"><div class="container"><div class="columns is-multiline"><?php foreach($stats as $label=>$val): ?><div class="column is-one-fifth"><a class="box stat-card" href="<?=e(url('page='.$label))?>"><div class="stat-label"><?=e(ucfirst($label))?></div><div class="stat-number"><?=number_format($val)?></div><div class="stat-foot">View records <span>?</span></div></a></div><?php endforeach ?><div class="column is-one-fifth"><a class="box stat-card harvest-stat" href="<?=e(url('page=reports'))?>"><div class="stat-label">Total harvest</div><div class="stat-number"><?=number_format($sum,0)?> <small>kg</small></div><div class="stat-foot">View reports <span>?</span></div></a></div></div><div class="columns mt-2"><div class="column is-8"><div class="box table-card"><div class="level"><div><p class="eyebrow">LATEST ACTIVITY</p><h2 class="title is-5">Recent harvests</h2></div><a href="<?=e(url('page=harvests'))?>" class="button is-small is-light">All harvests</a></div><div class="table-container"><table class="table is-fullwidth"><thead><tr><th>Date</th><th>Crop</th><th>Farm</th><th>Yield</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><?=e($row['harvest_date'])?></td><td><?=e($row['crop_name'])?></td><td><?=e($row['farm_name'])?></td><td><?=number_format((float)$row['quantity_kg'],2)?> kg</td></tr><?php endforeach ?><?php if(!$recent): ?><tr><td colspan="4" class="has-text-grey">Harvest records will appear here.</td></tr><?php endif ?></tbody></table></div></div></div><div class="column"><div class="box quick-box"><p class="eyebrow">QUICK ACTIONS</p><h2 class="title is-5">Keep things moving</h2><?php foreach(['farmers'=>'Register a farmer','plantings'=>'Record a planting','harvests'=>'Add a harvest','reports'=>'Open reports'] as $p=>$t): ?><a class="quick-link" href="<?=e(url('page='.$p))?>"><span><?=e($t)?></span><span>?</span></a><?php endforeach ?></div></div></div></div></section><?php require __DIR__.'/views/layout-bottom.php'; ?>